INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (2, "vo_minigame_1013_icon_2_002_001", 2, 1, "調子が上がって\nきたなっ", "vo_minigame_1013_icon_1_002_001", 1000, 2, 3000, "訓練はまだ\nここからですわ");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (2, "vo_minigame_1013_icon_2_003_001", 2, 2, "ほらほら、\nまだいけるだろ？", "vo_minigame_1013_icon_1_003_001", 5000, 2, 3000, "クスクス、悪くない\n流れですわね");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (2, "vo_minigame_1013_icon_2_004_001", 2, 3, "へへっ、おまえら\nやるじゃねえか！", "vo_minigame_1013_icon_1_004_001", 10000, 3, 3000, "すばらしい\n記録ですわ");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (3, "vo_minigame_1013_icon_2_005_001", 2, 4, "あたしたちはまだ\n止まらねえぜ！", "vo_minigame_1013_icon_1_005_001", 10000, 3, 3000, "乗りに乗って\nいますわね");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (3, "vo_minigame_1013_icon_2_005_002", 2, 5, "見てろよ！\nマコト班の快進撃だ！", "vo_minigame_1013_icon_1_005_002", 10000, 3, 3000, "まだまだ行きます\nついてきなさい");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (3, "vo_minigame_1013_icon_2_005_003", 2, 6, "うおぉぉっ！\n絶好調だぜ！", "vo_minigame_1013_icon_1_005_003", 10000, 3, 3000, "エリコ班の\n本領発揮ですわ！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (4, "vo_minigame_1013_icon_2_006_001", 2, 7, "どこまで行けるか\n楽しみだなっ！", "vo_minigame_1013_icon_1_006_001", 0, 3, 3000, "ここからは\n前人未到の領域です！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (5, "vo_minigame_1013_icon_2_007_001", 3, 8, "まだ諦めんなよっ", "vo_minigame_1013_icon_1_007_001", 1, 4, 1000, "厄介でしたわ…");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (5, "vo_minigame_1013_icon_2_007_002", 3, 9, "冷やっとしたぜ…！", "vo_minigame_1013_icon_1_007_002", 1, 4, 1000, "油断大敵です");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (5, "vo_minigame_1013_icon_2_007_003", 3, 10, "弱音を吐くなっ", "vo_minigame_1013_icon_1_007_003", 1, 4, 1000, "忌々しいっ…");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (6, "vo_minigame_1013_icon_2_008_001", 4, 11, "マコト班集合！", "vo_minigame_1013_icon_1_008_001", 99, 3, 1500, "大所帯ですわね");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (6, "vo_minigame_1013_icon_2_008_002", 4, 12, "連携してくぞ！", "vo_minigame_1013_icon_1_008_002", 99, 3, 1500, "エリコ班へようこそ");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (8, "vo_minigame_1013_icon_2_020_001", 1, 13, "みんなに力を！", "vo_minigame_1013_icon_1_020_001", 0, 6, 3000, "ナナカちゃんに\nお任せあれ");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (9, "vo_minigame_1013_icon_2_022_001", 1, 14, "任せてくれたまえ", "vo_minigame_1013_icon_1_022_001", 0, 7, 3000, "はっはっは！\n任せろ！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (10, "vo_minigame_1013_icon_2_023_001", 1, 15, "ほな、いきまひょか", "vo_minigame_1013_icon_1_023_001", 0, 8, 3000, "どんどんいくわよ");
